"use client";

import { useState } from "react";

export default function Counter() {
  const [count, setCount] = useState(0);

  return (
    <div className="flex flex-col items-center gap-4">
      <h1 className="text-3xl font-semibold">Contador</h1>
      <div className="flex items-center gap-4">
        <button
          type="button"
          onClick={() => setCount((c) => c - 1)}
          aria-label="Restar"
          className="h-10 w-10 rounded-md bg-gray-200 text-xl hover:bg-gray-300"
        >
          -
        </button>
        <span className="min-w-12 text-center text-2xl font-bold">{count}</span>
        <button
          type="button"
          onClick={() => setCount((c) => c + 1)}
          aria-label="Sumar"
          className="h-10 w-10 rounded-md bg-gray-200 text-xl hover:bg-gray-300"
        >
          +
        </button>
      </div>
      <p>El doble es {count * 2}</p>
      {count > 5 && <p className="font-medium text-green-600">¡Más de 5!</p>}
    </div>
  );
}

