"use client";

import { useRef, useState, type FormEvent } from "react";
import TodoItem, { type Todo } from "@/components/TodoItem";

export default function TodoList() {
  const [todos, setTodos] = useState<Todo[]>([]);
  const [text, setText] = useState("");
  const nextId = useRef(1);

  const addTodo = (e: FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    const title = text.trim();
    if (!title) return;
    setTodos((prev) => [
      ...prev,
      { id: nextId.current++, title, completed: false },
    ]);
    setText("");
  };

  const toggleTodo = (id: number) => {
    setTodos((prev) =>
      prev.map((t) => (t.id === id ? { ...t, completed: !t.completed } : t))
    );
  };

  const deleteTodo = (id: number) => {
    setTodos((prev) => prev.filter((t) => t.id !== id));
  };

  const pending = todos.filter((t) => !t.completed).length;

  return (
    <div className="w-full max-w-md rounded-2xl bg-gray-50 p-6 shadow-lg">
      <h1 className="mb-4 text-2xl font-bold text-gray-800">Lista de tareas</h1>

      <form onSubmit={addTodo} className="mb-4 flex gap-2">
        <input
          type="text"
          value={text}
          onChange={(e) => setText(e.target.value)}
          placeholder="¿Qué hay que hacer?"
          className="flex-1 rounded-lg border border-gray-300 px-3 py-2 text-gray-800 outline-none focus:border-blue-500 focus:ring-2 focus:ring-blue-200"
        />
        <button
          type="submit"
          className="rounded-lg bg-blue-600 px-4 py-2 font-medium text-white hover:bg-blue-700"
        >
          Agregar
        </button>
      </form>

      <ul className="mb-4 flex flex-col gap-2">
        {todos.map((todo) => (
          <TodoItem
            key={todo.id}
            todo={todo}
            onToggle={toggleTodo}
            onDelete={deleteTodo}
          />
        ))}
      </ul>

      <p className="text-sm text-gray-500">
        {todos.length === 0 ? "No hay tareas" : `${pending} pendientes`}
      </p>
    </div>
  );
}

