"use client";

import { useState } from "react";
import type { User } from "@/types/user";
import UserCard from "@/components/UserCard";

type UserSearchProps = {
  users: User[];
};

export default function UserSearch({ users }: UserSearchProps) {
  const [query, setQuery] = useState("");

  const normalizedQuery = query.trim().toLowerCase();
  const filteredUsers = users.filter((user) =>
    user.name.toLowerCase().includes(normalizedQuery)
  );

  const count = filteredUsers.length;

  return (
    <div className="space-y-4">
      <label htmlFor="user-search" className="sr-only">
        Buscar usuarios por nombre
      </label>
      <input
        id="user-search"
        type="search"
        value={query}
        onChange={(e) => setQuery(e.target.value)}
        placeholder="Buscar por nombre..."
        className="w-full rounded-md border border-gray-300 bg-white px-4 py-2 text-gray-900 placeholder-gray-500 focus:border-blue-500 focus:outline-none focus:ring-2 focus:ring-blue-500"
      />

      <p className="text-sm text-gray-600" aria-live="polite">
        {count} {count === 1 ? "resultado" : "resultados"}
      </p>

      {count > 0 ? (
        <ul className="grid gap-4 sm:grid-cols-2">
          {filteredUsers.map((user) => (
            <UserCard key={user.id} user={user} />
          ))}
        </ul>
      ) : (
        <p className="text-gray-500">No se encontraron usuarios.</p>
      )}
    </div>
  );
}

