"use client";

import { useMemo, useState } from "react";
import type { User } from "@/lib/users";
import UserCard from "@/components/UserCard";

type UserSearchProps = {
  users: User[];
};

export default function UserSearch({ users }: UserSearchProps) {
  const [query, setQuery] = useState("");

  const filteredUsers = useMemo(() => {
    const normalized = query.trim().toLowerCase();
    if (!normalized) return users;
    return users.filter((user) =>
      user.name.toLowerCase().includes(normalized)
    );
  }, [query, users]);

  const count = filteredUsers.length;

  return (
    <section className="w-full">
      <label
        htmlFor="user-search"
        className="mb-2 block text-sm font-medium text-gray-700 dark:text-gray-300"
      >
        Buscar por nombre
      </label>
      <input
        id="user-search"
        type="search"
        value={query}
        onChange={(e) => setQuery(e.target.value)}
        placeholder="Escribí un nombre..."
        className="w-full rounded-lg border border-gray-300 bg-white px-4 py-2 text-gray-900 placeholder-gray-400 outline-none focus:border-indigo-500 focus:ring-2 focus:ring-indigo-200 dark:border-gray-600 dark:bg-gray-800 dark:text-gray-100 dark:focus:ring-indigo-800"
      />

      <p
        aria-live="polite"
        className="mt-3 text-sm text-gray-600 dark:text-gray-400"
      >
        {count} {count === 1 ? "resultado" : "resultados"}
      </p>

      {count > 0 ? (
        <ul className="mt-4 grid gap-4 sm:grid-cols-2">
          {filteredUsers.map((user) => (
            <UserCard key={user.id} user={user} />
          ))}
        </ul>
      ) : (
        <p className="mt-4 rounded-lg border border-dashed border-gray-300 p-6 text-center text-gray-500 dark:border-gray-600 dark:text-gray-400">
          No se encontraron usuarios que coincidan con &quot;{query}&quot;.
        </p>
      )}
    </section>
  );
}

