"use client";

import { useState } from "react";

type Product = {
  id: number;
  nombre: string;
  precio: number;
};

type CartItem = Product & { cantidad: number };

const PRODUCTOS: Product[] = [
  { id: 1, nombre: "Camiseta", precio: 19.99 },
  { id: 2, nombre: "Pantalón", precio: 34.5 },
  { id: 3, nombre: "Zapatillas", precio: 59.9 },
];

export default function Cart() {
  const [items, setItems] = useState<CartItem[]>([]);

  const agregar = (producto: Product) => {
    setItems((prev) => {
      const existe = prev.find((i) => i.id === producto.id);
      if (existe) {
        return prev.map((i) =>
          i.id === producto.id ? { ...i, cantidad: i.cantidad + 1 } : i
        );
      }
      return [...prev, { ...producto, cantidad: 1 }];
    });
  };

  const incrementar = (id: number) => {
    setItems((prev) =>
      prev.map((i) => (i.id === id ? { ...i, cantidad: i.cantidad + 1 } : i))
    );
  };

  const decrementar = (id: number) => {
    setItems((prev) =>
      prev
        .map((i) => (i.id === id ? { ...i, cantidad: i.cantidad - 1 } : i))
        .filter((i) => i.cantidad > 0)
    );
  };

