"use client";

import { useState } from "react";

type Product = {
  id: number;
  nombre: string;
  precio: number;
};

type CartItem = Product & {
  cantidad: number;
};

const PRODUCTS: Product[] = [
  { id: 1, nombre: "Remera", precio: 15.99 },
  { id: 2, nombre: "Pantalón", precio: 39.5 },
  { id: 3, nombre: "Zapatillas", precio: 79.9 },
];

export default function ShoppingCart() {
  const [cart, setCart] = useState<CartItem[]>([]);

  const agregar = (product: Product) => {
    setCart((prev) => {
      const existe = prev.find((item) => item.id === product.id);
      if (existe) {
        return prev.map((item) =>
          item.id === product.id
            ? { ...item, cantidad: item.cantidad + 1 }
            : item
        );
      }
      return [...prev, { ...product, cantidad: 1 }];
    });
  };

  const incrementar = (id: number) => {
    setCart((prev) =>
      prev.map((item) =>
        item.id === id ? { ...item, cantidad: item.cantidad + 1 } : item
      )
    );
  };

  const decrementar = (id: number) => {
    setCart((prev) =>
      prev
        .map((item) =>
          item.id === id ? { ...item, cantidad: item.cantidad - 1 } : item
        )
        .filter((item) => item.cantidad > 0)
    );
  };

  const total = cart.reduce(
    (acc, item) => acc + item.precio * item.cantidad,
    0
  );

  return (
    <div className="grid gap-8 md:grid-cols-2">
      <section>
        <h2 className="mb-4 text-xl font-semibold text-gray-800">Productos</h2>
        <ul className="space-y-3">
          {PRODUCTS.map((product) => (
            <li
              key={product.id}
              className="flex items-center justify-between rounded-lg bg-white p-4 shadow-sm"
            >
              <div>
                <p className="font-medium text-gray-900">{product.nombre}</p>
                <p className="text-sm text-gray-500">
                  ${product.precio.toFixed(2)}
                </p>
              </div>
              <button
                onClick={() => agregar(product)}
                className="rounded-md bg-blue-600 px-4 py-2 text-sm font-medium text-white hover:bg-blue-700"
              >
                Agregar
              </button>
            </li>
          ))}
        </ul>
      </section>

      <section>
        <h2 className="mb-4 text-xl font-semibold text-gray-800">Carrito</h2>
        <div className="rounded-lg bg-white p-4 shadow-sm">
          {cart.length === 0 ? (
            <p className="text-gray-500">El carrito está vacío.</p>
          ) : (
            <ul className="divide-y divide-gray-100">
              {cart.map((item) => (
                <li
                  key={item.id}
                  className="flex items-center justify-between py-3"
                >
                  <div>
                    <p className="font-medium text-gray-900">{item.nombre}</p>
                    <p className="text-sm text-gray-500">
                      ${(item.precio * item.cantidad).toFixed(2)}
                    </p>
                  </div>
                  <div className="flex items-center gap-2">
                    <button
                      onClick={() => decrementar(item.id)}
                      className="h-8 w-8 rounded-md bg-gray-200 font-bold text-gray-700 hover:bg-gray-300"
                      aria-label={`Quitar una unidad de ${item.nombre}`}
                    >
                      -
                    </button>
                    <span className="w-6 text-center font-medium">
                      {item.cantidad}
                    </span>
                    <button
                      onClick={() => incrementar(item.id)}
                      className="h-8 w-8 rounded-md bg-gray-200 font-bold text-gray-700 hover:bg-gray-300"
                      aria-label={`Agregar una unidad de ${item.nombre}`}
                    >
                      +
                    </button>
                  </div>
                </li>
              ))}
            </ul>
          )}
          <div className="mt-4 flex justify-between border-t border-gray-200 pt-4 text-lg font-semibold text-gray-900">
            <span>Total</span>
            <span>${total.toFixed(2)}</span>
          </div>
        </div>
      </section>
    </div>
  );
}

