      ))}
      {todos.length === 0 ? <span className="text-gray-500">No hay tareas</span> : <span className="text-gray-500">{pending} pendientes</span>}
      {completed > 0 && (
        <button className="danger" onClick={clearCompleted}>Borrar completadas</button>
      )}
    </div>
  );
}

