export type User = {
  id: string;
  name: string;
  email: string;
};

type DB = {
  users: User[];
  nextId: number;
};

const globalForDb = globalThis as unknown as { __usersDb?: DB };

if (!globalForDb.__usersDb) {
  globalForDb.__usersDb = { users: [], nextId: 1 };
}

export const db: DB = globalForDb.__usersDb;

export function listUsers(): User[] {
  return db.users;
}

export function addUser(name: string, email: string): User {
  const user: User = { id: String(db.nextId++), name, email };
  db.users.push(user);
  return user;
}

export function deleteUser(id: string): boolean {
  const index = db.users.findIndex((u) => u.id === id);
  if (index === -1) return false;
  db.users.splice(index, 1);
  return true;
}

