import { useEffect, useState } from "react";

type Item = {
  id: string;
  name: string;
  bought: boolean;
};

export default function ShoppingList() {
  const [items, setItems] = useState<Item[]>([]);
  const [name, setName] = useState("");
  const [loading, setLoading] = useState(true);

  async function load() {
    try {
      const res = await fetch("/api/items", { cache: "no-store" });
      if (res.ok) setItems(await res.json());
    } finally {
      setLoading(false);
    }
  }

  useEffect(() => {
    load();
  }, []);

  async function add(e: React.FormEvent) {
    e.preventDefault();
    const trimmed = name.trim();
    if (!trimmed) return;
    const res = await fetch("/api/items", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ name: trimmed }),
    });
    if (res.ok) {
      const item: Item = await res.json();
      setItems((prev) => [...prev, item]);
      setName("");
    }
  }

  async function markBought(id: string) {
    const res = await fetch(`/api/items/${id}`, {
      method: "PATCH",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ bought: true }),
    });
    if (res.ok) {
      const updated: Item = await res.json();
      setItems((prev) => prev.map((i) => (i.id === id ? updated : i)));
    }
  }

  async function remove(id: string) {
    const res = await fetch(`/api/items/${id}`, { method: "DELETE" });
    if (res.ok) {
      setItems((prev) => prev.filter((i) => i.id !== id));
    }
  }

  const pending = items.filter((i) => !i.bought).length;

  return (
    <div className="w-full max-w-md rounded-xl bg-white p-6 shadow">
      <h1 className="mb-2 text-2xl font-bold text-gray-800">Lista de compras</h1>
      <p className="mb-4 text-gray-600">{pending} por comprar</p>

      <form onSubmit={add} className="mb-4 flex gap-2">
        <input
          value={name}
          onChange={(e) => setName(e.target.value)}
          placeholder="Producto"
          className="flex-1 rounded border border-gray-300 px-3 py-2 text-gray-800 focus:outline-none focus:ring-2 focus:ring-blue-400"
        />
        <button
          type="submit"
          className="rounded bg-blue-600 px-4 py-2 font-medium text-white hover:bg-blue-700"
        >
          Agregar
        </button>
      </form>

      {loading ? (
        <p className="text-gray-400">Cargando...</p>
      ) : (
        <ul className="space-y-2">
          {items.map((item) => (
            <li
              key={item.id}
              className="flex items-center justify-between rounded border border-gray-200 px-3 py-2"
            >
              <span
                className={
                  item.bought ? "text-gray-400 line-through" : "text-gray-800"
                }
              >
                {item.name}
                {item.bought && <span className="ml-2 text-green-600">✓</span>}
              </span>
              <div className="flex gap-2">
                <button
                  onClick={() => markBought(item.id)}
                  disabled={item.bought}
                  className="rounded bg-green-600 px-3 py-1 text-sm text-white hover:bg-green-700 disabled:opacity-50"
                >
                  Comprado
                </button>
                <button
                  onClick={() => remove(item.id)}
                  className="rounded bg-red-600 px-3 py-1 text-sm text-white hover:bg-red-700"
                >
                  Borrar
                </button>
              </div>
            </li>
          ))}
        </ul>
      )}
    </div>
  );
}

