  const load = useCallback(async () => {
    const [aRes, pRes] = await Promise.all([
      fetch("/api/authors", { cache: "no-store" }),
      fetch("/api/posts", { cache: "no-store" }),
    ]);
    const a: Author[] = await aRes.json();
    const p: Post[] = await pRes.json();
    setAuthors(a);
    setPosts(p);
    setSelectedAuthor((prev) =>
      a.some((x) => x.id === prev) ? prev : a[0]?.id ?? ""
    );
  }, []);

  useEffect(() => {
    load();
  }, [load]);

  async function createAuthor() {
    const name = authorName.trim();
    if (!name) return;
    const res = await fetch("/api/authors", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ name }),
    });
    if (res.ok) {
      setAuthorName("");
      setMessage("");
      await load();
    }
  }

  async function publish() {
    const t = title.trim();
    if (!t || !selectedAuthor) return;
    const res = await fetch("/api/posts", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ title: t, authorId: selectedAuthor }),
    });
    if (res.ok) {
      setTitle("");
      setMessage("");
      await load();
    }
  }

  async function deleteAuthor(id: string) {
    const res = await fetch(`/api/authors?id=${encodeURIComponent(id)}`, {
      method: "DELETE",
    });
    if (res.status === 409) {
      setMessage("El autor tiene posts");
      return;
    }
    if (res.ok) {
      setMessage("");
    }
    await load();
  }

  return (
