                onClick={() => deleteAuthor(a.id)}
              >
                Borrar autor
              </button>
            </li>
          ))}
        </ul>
      </section>

      <section className="space-y-3">
        <h2 className="text-xl font-semibold">Posts</h2>
        <div className="flex flex-wrap gap-2">
          <input
            className="flex-1 rounded border px-3 py-2"
