import { NextResponse } from "next/server";
import { db, Producto } from "@/lib/db";

export const dynamic = "force-dynamic";

export async function GET() {
  return NextResponse.json(db.productos);
}

export async function POST(request: Request) {
  let body: unknown;
  try {
    body = await request.json();
  } catch {
    return NextResponse.json({ error: "Datos inválidos" }, { status: 400 });
  }

  const data = (body ?? {}) as Record<string, unknown>;
  const nombre = typeof data.nombre === "string" ? data.nombre.trim() : "";
  const codigo =
    typeof data.codigo === "string"
      ? data.codigo.trim()
      : data.codigo != null
      ? String(data.codigo).trim()
      : "";
  const precioRaw = data.precio;
  const precio =
    typeof precioRaw === "number"
      ? precioRaw
      : typeof precioRaw === "string" && precioRaw.trim() !== ""
      ? Number(precioRaw)
      : NaN;

  if (nombre.length < 3) {
    return NextResponse.json({ error: "Nombre muy corto" }, { status: 400 });
  }

  if (db.productos.some((p) => p.codigo === codigo)) {
    return NextResponse.json({ error: "Código repetido" }, { status: 409 });
  }

  if (!Number.isFinite(precio) || precio < 0) {
    return NextResponse.json({ error: "Precio inválido" }, { status: 400 });
  }

  const producto: Producto = {
    id: `${Date.now()}-${Math.random().toString(36).slice(2, 9)}`,
    nombre,
    codigo,
    precio,
  };

  db.productos.push(producto);

  return NextResponse.json(producto, { status: 201 });
}

