"use client";

import { useEffect, useState } from "react";

type Producto = {
  id: string;
  nombre: string;
  codigo: string;
  precio: number;
};

export default function RegistroProductos() {
  const [productos, setProductos] = useState<Producto[]>([]);
  const [nombre, setNombre] = useState("");
  const [codigo, setCodigo] = useState("");
  const [precio, setPrecio] = useState("");
  const [error, setError] = useState("");
  const [guardando, setGuardando] = useState(false);

  useEffect(() => {
    let activo = true;
    fetch("/api/productos", { cache: "no-store" })
      .then((r) => r.json())
      .then((data: Producto[]) => {
        if (activo && Array.isArray(data)) setProductos(data);
      })
      .catch(() => {});
    return () => {
      activo = false;
    };
  }, []);

  async function guardar(e: React.FormEvent) {
    e.preventDefault();
    if (guardando) return;
    setGuardando(true);
    setError("");
    try {
      const res = await fetch("/api/productos", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ nombre, codigo, precio }),
      });
      const data = await res.json();
      if (!res.ok) {
        setError(data?.error ?? "Error al guardar");
        return;
      }
      setProductos((prev) => [...prev, data as Producto]);
      setNombre("");
      setCodigo("");
      setPrecio("");
    } catch {
      setError("Error al guardar");
    } finally {
      setGuardando(false);
    }
  }

  return (
    <div className="mx-auto max-w-xl p-6">
      <h1 className="mb-4 text-2xl font-bold">Registro de productos</h1>
      <form onSubmit={guardar} className="flex flex-col gap-3">
        <input
          className="rounded border px-3 py-2"
          placeholder="Nombre"
          value={nombre}
          onChange={(e) => setNombre(e.target.value)}
        />
        <input
          className="rounded border px-3 py-2"
          placeholder="Código"
          value={codigo}
          onChange={(e) => setCodigo(e.target.value)}
        />
        <input
          className="rounded border px-3 py-2"
          placeholder="Precio"
          type="number"
          step="any"
          value={precio}
          onChange={(e) => setPrecio(e.target.value)}
        />
        <button
          type="submit"
          disabled={guardando}
          className="rounded bg-blue-600 px-4 py-2 text-white hover:bg-blue-700 disabled:opacity-60"
        >
          Guardar
        </button>
      </form>
      {error && (
        <p role="alert" className="mt-3 text-red-600">
          {error}
        </p>
      )}
      <ul className="mt-6 flex flex-col gap-2">
        {productos.map((p) => (
          <li key={p.id} className="rounded border px-3 py-2">
            <span className="font-medium">{p.nombre}</span>{" "}
            <span className="text-gray-600">{p.codigo}</span>
          </li>
        ))}
      </ul>
    </div>
  );
}

