import { getPhoto, setPhoto } from "@/lib/db";

export const dynamic = "force-dynamic";

const MAX_SIZE = 10 * 1024 * 1024;

export async function GET() {
  const photo = getPhoto();
  if (!photo) {
    return Response.json({ hasPhoto: false });
  }
  return Response.json({
    hasPhoto: true,
    version: photo.version,
    name: photo.name,
    size: photo.size,
    contentType: photo.contentType,
  });
}

export async function POST(request: Request) {
  let formData: FormData;
  try {
    formData = await request.formData();
  } catch {
    return Response.json({ error: "Formato de solicitud inválido" }, { status: 400 });
  }

  const file = formData.get("file");
  if (!file || typeof file === "string") {
    return Response.json({ error: "No se recibió ningún archivo" }, { status: 400 });
  }

  if (!file.type.startsWith("image/")) {
    return Response.json({ error: "El archivo debe ser una imagen" }, { status: 400 });
  }

  if (file.size === 0) {
    return Response.json({ error: "El archivo está vacío" }, { status: 400 });
  }

  if (file.size > MAX_SIZE) {
    return Response.json({ error: "La imagen supera los 10 MB" }, { status: 413 });
  }

  const data = await file.arrayBuffer();
  const stored = setPhoto({
    data,
    contentType: file.type,
    name: file.name,
    size: file.size,
  });

  return Response.json(
    {
      hasPhoto: true,
      version: stored.version,
      name: stored.name,
      size: stored.size,
      contentType: stored.contentType,
    },
    { status: 201 }
  );
}

