"use client";

import { useEffect, useRef, useState } from "react";

type PhotoInfo =
  | { hasPhoto: false }
  | { hasPhoto: true; version: number; name: string; size: number; contentType: string };

export default function ProfilePhoto() {
  const [info, setInfo] = useState<PhotoInfo | null>(null);
  const [file, setFile] = useState<File | null>(null);
  const [uploading, setUploading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [message, setMessage] = useState<string | null>(null);
  const inputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    let cancelled = false;
    fetch("/api/photo", { cache: "no-store" })
      .then((r) => r.json())
      .then((data: PhotoInfo) => {
        if (!cancelled) setInfo(data);
      })
      .catch(() => {
        if (!cancelled) {
          setInfo({ hasPhoto: false });
          setError("No se pudo cargar la foto");
        }
      });
    return () => {
      cancelled = true;
    };
  }, []);

  async function handleUpload() {
    if (!file) {
      setError("Elegí una foto primero");
      return;
    }
    setUploading(true);
    setError(null);
    setMessage(null);
    try {
      const fd = new FormData();
      fd.append("file", file);
      const res = await fetch("/api/photo", { method: "POST", body: fd });
      const data = await res.json();
      if (!res.ok) {
        setError(data.error ?? "Error al subir la foto");
        return;
      }
      setInfo(data as PhotoInfo);
      setFile(null);
      if (inputRef.current) inputRef.current.value = "";
      setMessage("Foto subida correctamente");
    } catch {
      setError("Error de red al subir la foto");
    } finally {
      setUploading(false);
    }
  }

  return (
    <div className="w-full max-w-md rounded-2xl bg-white p-6 shadow-lg">
      <h1 className="mb-6 text-2xl font-bold text-gray-900">Mi perfil</h1>

      <div className="flex flex-col gap-3">
        <label htmlFor="photo" className="text-sm font-medium text-gray-700">
          Foto de perfil
        </label>
        <input
          ref={inputRef}
          id="photo"
          type="file"
          accept="image/*"
          onChange={(e) => {
            setFile(e.target.files?.[0] ?? null);
            setError(null);
            setMessage(null);
          }}
          className="block w-full text-sm text-gray-700 file:mr-4 file:rounded-lg file:border-0 file:bg-gray-100 file:px-4 file:py-2 file:text-sm file:font-medium file:text-gray-800 hover:file:bg-gray-200"
        />
        <button
          type="button"
          onClick={handleUpload}
          disabled={uploading || !file}
          className="rounded-lg bg-blue-600 px-4 py-2 font-medium text-white transition hover:bg-blue-700 disabled:cursor-not-allowed disabled:opacity-50"
        >
          {uploading ? "Subiendo..." : "Subir"}
        </button>
        {error && <p className="text-sm text-red-600">{error}</p>}
        {message && <p className="text-sm text-green-600">{message}</p>}
      </div>

      <div className="mt-8 flex flex-col items-center">
        {info === null ? (
          <p className="text-sm text-gray-500">Cargando...</p>
        ) : info.hasPhoto ? (
          <>
            {/* eslint-disable-next-line @next/next/no-img-element */}
            <img
              src={`/api/photo/image?v=${info.version}`}
              alt="Foto de perfil"
              className="h-48 w-48 rounded-full border-4 border-gray-100 object-cover shadow"
            />
            <p className="mt-3 text-xs text-gray-500">{info.name}</p>
          </>
        ) : (
          <div className="flex h-48 w-48 items-center justify-center rounded-full bg-gray-100 text-sm text-gray-400">
            Sin foto
          </div>
        )}
      </div>
    </div>
  );
}

