"use client";

import { useState } from "react";

type ContactType = "Amigo" | "Trabajo";

interface Contact {
  id: number;
  name: string;
  type: ContactType;
}

export default function ContactList() {
  const [contacts, setContacts] = useState<Contact[]>([]);
  const [open, setOpen] = useState(false);
  const [name, setName] = useState("");
  const [type, setType] = useState<ContactType>("Amigo");
  const [nextId, setNextId] = useState(1);

  const resetForm = () => {
    setName("");
    setType("Amigo");
  };

  const openDialog = () => {
    resetForm();
    setOpen(true);
  };

  const closeDialog = () => {
    setOpen(false);
    resetForm();
  };

  const save = () => {
    const trimmed = name.trim();
    if (!trimmed) return;
    setContacts((prev) => [...prev, { id: nextId, name: trimmed, type }]);
    setNextId((n) => n + 1);
    closeDialog();
  };

  return (
    <div>
      <button
        type="button"
        onClick={openDialog}
        className="rounded-md bg-blue-600 px-4 py-2 text-white hover:bg-blue-700"
      >
        Nuevo contacto
      </button>

      <ul className="mt-6 space-y-2">
        {contacts.map((c) => (
          <li
            key={c.id}
            className="rounded-md border border-gray-200 bg-white px-4 py-2 text-gray-800"
          >
            {c.name} ({c.type})
          </li>
        ))}
      </ul>

      {open && (
        <div
          className="fixed inset-0 z-50 flex items-center justify-center bg-black/50"
          onClick={closeDialog}
        >
          <div
            role="dialog"
            aria-modal="true"
            aria-labelledby="dialog-title"
            className="w-full max-w-sm rounded-lg bg-white p-6 shadow-xl"
            onClick={(e) => e.stopPropagation()}
            onKeyDown={(e) => {
              if (e.key === "Escape") closeDialog();
            }}
          >
            <h2 id="dialog-title" className="mb-4 text-lg font-semibold text-gray-900">
              Nuevo contacto
            </h2>
            <form
              onSubmit={(e) => {
                e.preventDefault();
                save();
              }}
              className="space-y-4"
            >
              <input
                type="text"
                placeholder="Nombre"
                value={name}
                onChange={(e) => setName(e.target.value)}
                autoFocus
                className="w-full rounded-md border border-gray-300 px-3 py-2 text-gray-900"
              />
              <select
                value={type}
                onChange={(e) => setType(e.target.value as ContactType)}
                className="w-full rounded-md border border-gray-300 px-3 py-2 text-gray-900"
              >
                <option value="Amigo">Amigo</option>
                <option value="Trabajo">Trabajo</option>
              </select>
              <div className="flex justify-end gap-2">
                <button
                  type="button"
                  onClick={closeDialog}
                  className="rounded-md border border-gray-300 px-4 py-2 text-gray-700 hover:bg-gray-100"
                >
                  Cancelar
                </button>
                <button
                  type="submit"
                  className="rounded-md bg-blue-600 px-4 py-2 text-white hover:bg-blue-700"
                >
                  Guardar
                </button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
}

