"use client";

import { useEffect, useRef, useState } from "react";

type ContactType = "Amigo" | "Trabajo";

interface Contact {
  id: number;
  name: string;
  type: ContactType;
}

export default function ContactList() {
  const [contacts, setContacts] = useState<Contact[]>([]);
  const [open, setOpen] = useState(false);
  const [name, setName] = useState("");
  const [type, setType] = useState<ContactType>("Amigo");
  const nextId = useRef(1);
  const inputRef = useRef<HTMLInputElement>(null);
  const triggerRef = useRef<HTMLButtonElement>(null);
  const wasOpen = useRef(false);

  const openDialog = () => {
    setName("");
    setType("Amigo");
    setOpen(true);
  };

  const closeDialog = () => {
    setOpen(false);
  };

  const save = () => {
    const trimmed = name.trim();
    if (!trimmed) return;
    setContacts((prev) => [
      ...prev,
      { id: nextId.current++, name: trimmed, type },
    ]);
    closeDialog();
  };

  useEffect(() => {
    if (open) {
      inputRef.current?.focus();
    } else if (wasOpen.current) {
      triggerRef.current?.focus();
    }
    wasOpen.current = open;
  }, [open]);

  useEffect(() => {
    if (!open) return;
    const onKey = (e: KeyboardEvent) => {
      if (e.key === "Escape") closeDialog();
    };
    document.addEventListener("keydown", onKey);
    return () => document.removeEventListener("keydown", onKey);
  }, [open]);

  return (
    <div>
      <button
        ref={triggerRef}
        type="button"
        onClick={openDialog}
        className="rounded-md bg-blue-600 px-4 py-2 font-medium text-white hover:bg-blue-700"
      >
        Nuevo contacto
      </button>

      {contacts.length === 0 ? (
        <p className="mt-6 text-gray-500">No hay contactos todavía.</p>
      ) : (
        <ul className="mt-6 divide-y divide-gray-200 rounded-md border border-gray-200 bg-white">
          {contacts.map((c) => (
            <li key={c.id} className="px-4 py-3 text-gray-800">
              {`${c.name} (${c.type})`}
            </li>
          ))}
        </ul>
      )}

      {open && (
        <div
          className="fixed inset-0 z-50 flex items-center justify-center bg-black/50 p-4"
          onClick={closeDialog}
        >
          <div
            role="dialog"
            aria-modal="true"
            aria-labelledby="dialog-title"
            className="w-full max-w-sm rounded-lg bg-white p-6 shadow-xl"
            onClick={(e) => e.stopPropagation()}
          >
            <h2
              id="dialog-title"
              className="mb-4 text-lg font-semibold text-gray-900"
            >
              Nuevo contacto
            </h2>
            <form
              onSubmit={(e) => {
                e.preventDefault();
                save();
              }}
              className="space-y-4"
            >
              <input
                ref={inputRef}
                type="text"
                placeholder="Nombre"
                aria-label="Nombre"
                value={name}
                onChange={(e) => setName(e.target.value)}
                className="w-full rounded-md border border-gray-300 px-3 py-2 text-gray-900 focus:border-blue-500 focus:outline-none"
              />
              <select
                aria-label="Tipo"
                value={type}
                onChange={(e) => setType(e.target.value as ContactType)}
                className="w-full rounded-md border border-gray-300 px-3 py-2 text-gray-900 focus:border-blue-500 focus:outline-none"
              >
                <option value="Amigo">Amigo</option>
                <option value="Trabajo">Trabajo</option>
              </select>
              <div className="flex justify-end gap-2">
                <button
                  type="button"
                  onClick={closeDialog}
                  className="rounded-md border border-gray-300 px-4 py-2 text-gray-700 hover:bg-gray-100"
                >
                  Cancelar
                </button>
                <button
                  type="submit"
                  className="rounded-md bg-blue-600 px-4 py-2 font-medium text-white hover:bg-blue-700"
                >
                  Guardar
                </button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
}

