"use client";

import { useState } from "react";

const TOTAL_ITEMS = 23;
const POR_PAGINA = 10;
const ITEMS = Array.from({ length: TOTAL_ITEMS }, (_, i) => `Ítem ${i + 1}`);
const TOTAL_PAGINAS = Math.ceil(TOTAL_ITEMS / POR_PAGINA);

export default function Paginacion() {
  const [pagina, setPagina] = useState(1);

  const inicio = (pagina - 1) * POR_PAGINA;
  const visibles = ITEMS.slice(inicio, inicio + POR_PAGINA);

  const esPrimera = pagina === 1;
  const esUltima = pagina === TOTAL_PAGINAS;

  return (
    <div className="w-full max-w-md bg-white rounded-lg shadow p-6">
      <ul className="divide-y divide-gray-200 mb-6">
        {visibles.map((item) => (
          <li key={item} className="py-2 text-gray-800">
            {item}
          </li>
        ))}
      </ul>

      <p className="text-center text-gray-600 mb-4">
        Página {pagina} de {TOTAL_PAGINAS}
      </p>

      <div className="flex justify-between gap-4">
        <button
          type="button"
          onClick={() => setPagina((p) => Math.max(1, p - 1))}
          disabled={esPrimera}
          className="flex-1 px-4 py-2 rounded bg-blue-600 text-white font-medium hover:bg-blue-700 disabled:bg-gray-300 disabled:text-gray-500 disabled:cursor-not-allowed"
        >
          Anterior
        </button>
        <button
          type="button"
          onClick={() => setPagina((p) => Math.min(TOTAL_PAGINAS, p + 1))}
          disabled={esUltima}
          className="flex-1 px-4 py-2 rounded bg-blue-600 text-white font-medium hover:bg-blue-700 disabled:bg-gray-300 disabled:text-gray-500 disabled:cursor-not-allowed"
        >
          Siguiente
        </button>
      </div>
    </div>
  );
}

