"use client";

import { useMemo, useState } from "react";

type Employee = {
  nombre: string;
  edad: number;
};

const INITIAL_EMPLOYEES: Employee[] = [
  { nombre: "Caro", edad: 35 },
  { nombre: "Ana", edad: 30 },
  { nombre: "Dani", edad: 28 },
  { nombre: "Beto", edad: 25 },
];

type SortKey = "none" | "nombre" | "edad";

export default function EmployeeTable() {
  const [sortKey, setSortKey] = useState<SortKey>("none");
  const [filter, setFilter] = useState("");

  const visibleEmployees = useMemo(() => {
    const term = filter.trim().toLowerCase();
    const filtered = INITIAL_EMPLOYEES.filter((e) =>
      e.nombre.toLowerCase().includes(term)
    );
    if (sortKey === "nombre") {
      return [...filtered].sort((a, b) => a.nombre.localeCompare(b.nombre));
    }
    if (sortKey === "edad") {
      return [...filtered].sort((a, b) => a.edad - b.edad);
    }
    return filtered;
  }, [sortKey, filter]);

  return (
    <div className="max-w-md space-y-4">
      <div className="flex flex-wrap gap-2">
        <button
          type="button"
          onClick={() => setSortKey("nombre")}
          className="rounded bg-blue-600 px-4 py-2 text-white hover:bg-blue-700"
        >
          Ordenar por nombre
        </button>
        <button
          type="button"
          onClick={() => setSortKey("edad")}
          className="rounded bg-blue-600 px-4 py-2 text-white hover:bg-blue-700"
        >
          Ordenar por edad
        </button>
      </div>

      <input
        type="text"
        placeholder="Filtrar"
        value={filter}
        onChange={(e) => setFilter(e.target.value)}
        className="w-full rounded border border-gray-300 px-3 py-2"
      />

      <table className="w-full border-collapse border border-gray-300">
        <thead>
          <tr className="bg-gray-100">
            <th className="border border-gray-300 px-4 py-2 text-left">Nombre</th>
            <th className="border border-gray-300 px-4 py-2 text-left">Edad</th>
          </tr>
        </thead>
        <tbody>
          {visibleEmployees.map((e) => (
            <tr key={e.nombre}>
              <td className="border border-gray-300 px-4 py-2">{e.nombre}</td>
              <td className="border border-gray-300 px-4 py-2">{e.edad}</td>
            </tr>
          ))}
        </tbody>
      </table>

      <p>Empleados: {visibleEmployees.length}</p>
    </div>
  );
}

