export type Task = {
  id: string;
  title: string;
  done: boolean;
};

type Store = {
  tasks: Task[];
  nextId: number;
};

const globalForDb = globalThis as unknown as { __taskStore?: Store };

if (!globalForDb.__taskStore) {
  globalForDb.__taskStore = { tasks: [], nextId: 1 };
}

const store = globalForDb.__taskStore;

export function getTasks(): Task[] {
  return store.tasks;
}

export function addTask(title: string): Task {
  const task: Task = { id: String(store.nextId++), title, done: false };
  store.tasks.push(task);
  return task;
}

export function updateTask(
  id: string,
  changes: Partial<Pick<Task, "title" | "done">>
): Task | null {
  const task = store.tasks.find((t) => t.id === id);
  if (!task) return null;
  if (typeof changes.title === "string") task.title = changes.title;
  if (typeof changes.done === "boolean") task.done = changes.done;
  return task;
}

