export type Task = {
  id: string;
  title: string;
  done: boolean;
};

type DB = {
  tasks: Task[];
  nextId: number;
};

const g = globalThis as unknown as { __tasksDb?: DB };

if (!g.__tasksDb) {
  g.__tasksDb = { tasks: [], nextId: 1 };
}

export const db: DB = g.__tasksDb;

export function listTasks(): Task[] {
  return db.tasks;
}

export function createTask(title: string): Task {
  const task: Task = { id: String(db.nextId++), title, done: false };
  db.tasks.push(task);
  return task;
}

export function updateTask(
  id: string,
  data: Partial<Pick<Task, "title" | "done">>
): Task | null {
  const task = db.tasks.find((t) => t.id === id);
  if (!task) return null;
  if (typeof data.title === "string") task.title = data.title;
  if (typeof data.done === "boolean") task.done = data.done;
  return task;
}

