"use client";

import { useEffect, useState } from "react";

type Task = {
  id: string;
  title: string;
  done: boolean;
};

type Filter = "todas" | "pendientes" | "hechas";

export default function TaskManager() {
  const [tasks, setTasks] = useState<Task[]>([]);
  const [newTitle, setNewTitle] = useState("");
  const [filter, setFilter] = useState<Filter>("todas");
  const [editingId, setEditingId] = useState<string | null>(null);
  const [editTitle, setEditTitle] = useState("");

  useEffect(() => {
    fetch("/api/tasks", { cache: "no-store" })
      .then((r) => r.json())
      .then((data: Task[]) => setTasks(data))
      .catch(() => {});
  }, []);

  async function addTask() {
    const title = newTitle.trim();
    if (!title) return;
    const res = await fetch("/api/tasks", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ title }),
    });
    if (!res.ok) return;
    const task: Task = await res.json();
    setTasks((prev) => [...prev, task]);
    setNewTitle("");
  }

  async function markDone(id: string) {
    const res = await fetch(`/api/tasks/${id}`, {
      method: "PATCH",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ done: true }),
    });
    if (!res.ok) return;
    const updated: Task = await res.json();
    setTasks((prev) => prev.map((t) => (t.id === id ? updated : t)));
  }

  function startRename(task: Task) {
    setEditingId(task.id);
    setEditTitle(task.title);
  }

  async function saveRename(id: string) {
    const title = editTitle.trim();
    if (!title) return;
    const res = await fetch(`/api/tasks/${id}`, {
      method: "PATCH",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ title }),
    });
    if (!res.ok) return;
    const updated: Task = await res.json();
    setTasks((prev) => prev.map((t) => (t.id === id ? updated : t)));
    setEditingId(null);
    setEditTitle("");
  }

  const visible = tasks.filter((t) =>
    filter === "todas" ? true : filter === "hechas" ? t.done : !t.done
  );

  return (
    <div className="space-y-4">
      <form
        className="flex gap-2"
        onSubmit={(e) => {
          e.preventDefault();
          addTask();
        }}
      >
        <input
          className="flex-1 rounded border px-3 py-2"
          placeholder="Tarea"
          value={newTitle}
          onChange={(e) => setNewTitle(e.target.value)}
        />
        <button
          type="submit"
          className="rounded bg-blue-600 px-4 py-2 text-white hover:bg-blue-700"
        >
          Agregar
        </button>
      </form>

      <select
        className="rounded border px-3 py-2"
        value={filter}
        onChange={(e) => setFilter(e.target.value as Filter)}
      >
        <option value="todas">Todas</option>
        <option value="pendientes">Pendientes</option>
        <option value="hechas">Hechas</option>
      </select>

      <ul className="space-y-2">
        {visible.map((task) => (
          <li
            key={task.id}
            className="flex items-center gap-2 rounded border p-2"
          >
            {editingId === task.id ? (
              <>
                <input
                  className="flex-1 rounded border px-2 py-1"
                  placeholder="Nuevo título"
                  value={editTitle}
                  onChange={(e) => setEditTitle(e.target.value)}
                  onKeyDown={(e) => {
                    if (e.key === "Enter") saveRename(task.id);
                  }}
                  autoFocus
                />
                <button
                  className="rounded bg-green-600 px-3 py-1 text-white hover:bg-green-700"
                  onClick={() => saveRename(task.id)}
                >
                  Guardar
                </button>
              </>
            ) : (
              <>
                <span className="flex-1">
                  <span className={task.done ? "line-through" : ""}>
                    {task.title}
                  </span>
                  {task.done && (
                    <span className="ml-2 text-gray-500">(hecha)</span>
                  )}
                </span>
                {!task.done && (
                  <button
                    className="rounded bg-gray-200 px-3 py-1 hover:bg-gray-300"
                    onClick={() => markDone(task.id)}
                  >
                    Hecha
                  </button>
                )}
                <button
                  className="rounded bg-gray-200 px-3 py-1 hover:bg-gray-300"
                  onClick={() => startRename(task)}
                >
                  Renombrar
                </button>
              </>
            )}
          </li>
        ))}
      </ul>
    </div>
  );
}

