  votos.perros = 0;
  votos.gatos = 0;
}

export function obtenerResultados() {
  const total = votos.perros + votos.gatos;
  const pct = (n: number) => (total === 0 ? 0 : Math.round((n / total) * 100));
  return {
    perros: { votos: votos.perros, porcentaje: pct(votos.perros) },
    gatos: { votos: votos.gatos, porcentaje: pct(votos.gatos) },
    total,
  };
}

