      const res = await fetch("/api/votes", { cache: "no-store" });
      if (!res.ok) throw new Error();
      setResults(await res.json());
      setError(null);
    } catch {
      setError("No se pudieron cargar los resultados.");
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    load();
  }, [load]);

  async function vote(choice: "perros" | "gatos") {
    setBusy(true);
    try {
      const res = await fetch("/api/votes", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ choice }),
      });
      if (!res.ok) throw new Error();
      setResults(await res.json());
      setError(null);
    } catch {
      setError("No se pudo registrar el voto.");
    } finally {
      setBusy(false);
    }
  }

  async function reset() {
    setBusy(true);
    try {
      const res = await fetch("/api/votes", { method: "DELETE" });
      if (!res.ok) throw new Error();
      setResults(await res.json());
      setError(null);
    } catch {
      setError("No se pudieron reiniciar los votos.");
    } finally {
      setBusy(false);
    }
  }

  return (
    <div className="w-full max-w-md rounded-2xl bg-white p-6 shadow-lg">
      <h1 className="mb-6 text-center text-2xl font-bold text-gray-800">
        ¿Perros o gatos?
      </h1>

      <div className="mb-6 grid grid-cols-2 gap-3">
        <button
          onClick={() => vote("perros")}
          disabled={busy || loading}
          className="rounded-lg bg-amber-500 px-4 py-3 font-semibold text-white transition hover:bg-amber-600 disabled:opacity-50"
        >
          Votar Perros
        </button>
        <button
          onClick={() => vote("gatos")}
          disabled={busy || loading}
          className="rounded-lg bg-indigo-500 px-4 py-3 font-semibold text-white transition hover:bg-indigo-600 disabled:opacity-50"
        >
          Votar Gatos
        </button>
      </div>

      {loading ? (
        <p className="text-center text-gray-500">Cargando...</p>
      ) : (
        <div className="space-y-4">
          <div>
            <p className="mb-1 font-medium text-gray-700">
              {`Perros: ${results.perros.percent}% (${results.perros.votes} votos)`}
            </p>
            <div className="h-3 w-full overflow-hidden rounded-full bg-gray-200">
              <div
                className="h-full bg-amber-500 transition-all"
                style={{ width: `${results.perros.percent}%` }}
              />
            </div>
          </div>
          <div>
            <p className="mb-1 font-medium text-gray-700">
              {`Gatos: ${results.gatos.percent}% (${results.gatos.votes} votos)`}
            </p>
            <div className="h-3 w-full overflow-hidden rounded-full bg-gray-200">
              <div
                className="h-full bg-indigo-500 transition-all"
                style={{ width: `${results.gatos.percent}%` }}
              />
            </div>
          </div>
        </div>
      )}

      {error && <p className="mt-4 text-center text-sm text-red-600">{error}</p>}

      <button
        onClick={reset}
        disabled={busy || loading}
        className="mt-6 w-full rounded-lg border border-gray-300 px-4 py-2 font-medium text-gray-700 transition hover:bg-gray-100 disabled:opacity-50"
      >
        Reiniciar
      </button>
    </div>
  );
}

