}

export const db: DB = globalForDb.__catalogDb;

export function seedProducts(): boolean {
  if (db.products.length > 0) return false;
  for (let i = 1; i <= 12; i++) {
    db.products.push({ id: i, name: `Producto ${i}` });
  }
  return true;
}

export function queryProducts(q: string, page: number, pageSize: number) {
  const term = q.trim().toLowerCase();
  const filtered = db.products
    .filter((p) => (term ? p.name.toLowerCase().includes(term) : true))
    .sort((a, b) => a.id - b.id);
  const total = filtered.length;
  const totalPages = Math.max(1, Math.ceil(total / pageSize));
  const safePage = Math.min(Math.max(1, page), totalPages);
  const start = (safePage - 1) * pageSize;
  const items = filtered.slice(start, start + pageSize);
  return { items, total, page: safePage, pageSize, totalPages };
}

