"use client";

import { useCallback, useEffect, useRef, useState } from "react";

type Product = { id: number; name: string };

type Result = {
  items: Product[];
  total: number;
  page: number;
  pageSize: number;
  totalPages: number;
};

export default function Catalog() {
  const [query, setQuery] = useState("");
  const [page, setPage] = useState(1);
  const [data, setData] = useState<Result>({
    items: [],
    total: 0,
    page: 1,
    pageSize: 5,
    totalPages: 1,
  });
  const [loading, setLoading] = useState(false);
  const [seeding, setSeeding] = useState(false);
  const requestId = useRef(0);

  const load = useCallback(async (q: string, p: number) => {
    const id = ++requestId.current;
    setLoading(true);
    try {
      const params = new URLSearchParams({ q, page: String(p) });
      const res = await fetch(`/api/products?${params.toString()}`, {
        cache: "no-store",
      });
      if (!res.ok) return;
      const json: Result = await res.json();
      if (id !== requestId.current) return;
      setData(json);
      if (json.page !== p) setPage(json.page);
    } finally {
      if (id === requestId.current) setLoading(false);
    }
  }, []);

  useEffect(() => {
    load(query, page);
  }, [query, page, load]);

  const handleSeed = async () => {
    setSeeding(true);
    try {
      await fetch("/api/products", { method: "POST" });
      await load(query, page);
    } finally {
      setSeeding(false);
    }
  };

  const canPrev = data.page > 1;
  const canNext = data.page < data.totalPages;

  return (
    <div className="mx-auto max-w-xl p-6 space-y-4">
      <h1 className="text-2xl font-bold">Catálogo</h1>

      <div className="flex gap-2">
        <button
          onClick={handleSeed}
          disabled={seeding}
          className="rounded bg-blue-600 px-4 py-2 text-white hover:bg-blue-700 disabled:opacity-50"
        >
          Cargar ejemplos
        </button>
        <input
          type="text"
          placeholder="Buscar"
          value={query}
          onChange={(e) => {
            setQuery(e.target.value);
            setPage(1);
          }}
          className="flex-1 rounded border border-gray-300 px-3 py-2"
        />
      </div>

      <p className="text-sm text-gray-700">Total: {data.total}</p>

      <ul className="divide-y rounded border border-gray-200">
        {data.items.length === 0 ? (
          <li className="p-3 text-gray-500">
            {loading ? "Cargando..." : "No hay productos"}
          </li>
        ) : (
          data.items.map((p) => (
            <li key={p.id} className="p-3">
              {p.name}
            </li>
          ))
        )}
      </ul>

      <div className="flex items-center justify-between">
        <button
          onClick={() => canPrev && setPage(data.page - 1)}
          disabled={!canPrev}
          className="rounded border px-4 py-2 disabled:opacity-50"
        >
          Anterior
        </button>
        <span className="text-sm text-gray-600">
          Página {data.page} de {data.totalPages}
        </span>
        <button
          onClick={() => canNext && setPage(data.page + 1)}
          disabled={!canNext}
          className="rounded border px-4 py-2 disabled:opacity-50"
        >
          Siguiente
        </button>
      </div>
    </div>
  );
}

