import { randomBytes, scryptSync, timingSafeEqual } from "crypto";

export type User = {
  email: string;
  salt: string;
  hash: string;
};

export type Note = {
  id: string;
  owner: string;
  text: string;
  createdAt: number;
};

type DB = {
  users: Map<string, User>;
  sessions: Map<string, string>;
  notes: Note[];
};

const g = globalThis as unknown as { __notesDb?: DB };

if (!g.__notesDb) {
  g.__notesDb = {
    users: new Map(),
    sessions: new Map(),
    notes: [],
  };
}

export const db: DB = g.__notesDb;

export const SESSION_COOKIE = "session";

export function hashPassword(password: string, salt: string): string {
  return scryptSync(password, salt, 64).toString("hex");
}

export function createUser(email: string, password: string): User | null {
  if (db.users.has(email)) return null;
  const salt = randomBytes(16).toString("hex");
  const user: User = { email, salt, hash: hashPassword(password, salt) };
  db.users.set(email, user);
  return user;
}

export function verifyUser(email: string, password: string): User | null {
  const user = db.users.get(email);
  if (!user) return null;
  const candidate = Buffer.from(hashPassword(password, user.salt), "hex");
  const stored = Buffer.from(user.hash, "hex");
  if (candidate.length !== stored.length) return null;
  return timingSafeEqual(candidate, stored) ? user : null;
}

export function createSession(email: string): string {
  const token = randomBytes(32).toString("hex");
  db.sessions.set(token, email);
  return token;
}

export function getSessionEmail(token: string | undefined): string | null {
  if (!token) return null;
  return db.sessions.get(token) ?? null;
}

export function deleteSession(token: string | undefined) {
  if (token) db.sessions.delete(token);
}

export function normalizeEmail(email: unknown): string {
  return typeof email === "string" ? email.trim().toLowerCase() : "";
}

