import { NextRequest, NextResponse } from "next/server";
import { randomBytes } from "crypto";
import { db } from "@/lib/db";
import { getRequestEmail } from "@/lib/session";

export const dynamic = "force-dynamic";

export async function GET(req: NextRequest) {
  const email = getRequestEmail(req);
  if (!email) {
    return NextResponse.json({ error: "No autorizado" }, { status: 401 });
  }
  const notes = db.notes
    .filter((n) => n.owner === email)
    .map(({ id, text, createdAt }) => ({ id, text, createdAt }));
  return NextResponse.json({ notes });
}

export async function POST(req: NextRequest) {
  const email = getRequestEmail(req);
  if (!email) {
    return NextResponse.json({ error: "No autorizado" }, { status: 401 });
  }
  let body: { text?: unknown } = {};
  try {
    body = await req.json();
  } catch {}
  const text = typeof body.text === "string" ? body.text.trim() : "";
  if (!text) {
    return NextResponse.json({ error: "La nota está vacía" }, { status: 400 });
  }
  const note = {
    id: randomBytes(8).toString("hex"),
    owner: email,
    text,
    createdAt: Date.now(),
  };
  db.notes.push(note);
  return NextResponse.json(
    { note: { id: note.id, text: note.text, createdAt: note.createdAt } },
    { status: 201 }
  );
}

