import { useEffect, useState } from "react";

type Note = { id: string; text: string; createdAt: number };

export default function NotesApp() {
  const [loading, setLoading] = useState(true);
  const [user, setUser] = useState<string | null>(null);
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [error, setError] = useState("");
  const [notes, setNotes] = useState<Note[]>([]);
  const [noteText, setNoteText] = useState("");

  async function loadNotes() {
    const res = await fetch("/api/notes", { cache: "no-store" });
    if (res.ok) {
      const data = await res.json();
      setNotes(data.notes);
    } else {
      setNotes([]);
    }
  }

  useEffect(() => {
    (async () => {
      try {
        const res = await fetch("/api/me", { cache: "no-store" });
        if (res.ok) {
          const data = await res.json();
          setUser(data.email);
          await loadNotes();
        }
      } finally {
        setLoading(false);
      }
    })();
  }, []);

  async function auth(kind: "register" | "login") {
    setError("");
    try {
      const res = await fetch(`/api/${kind}`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ email, password }),
      });
      const data = await res.json().catch(() => ({}));
      if (!res.ok) {
        setError(kind === "login" ? "Datos incorrectos" : data.error || "Error");
        return;
      }
      setUser(data.email);
      setPassword("");
      await loadNotes();
    } catch {
      setError("Error de conexión");
    }
  }

  async function logout() {
    await fetch("/api/logout", { method: "POST" });
    setUser(null);
    setNotes([]);
    setEmail("");
    setPassword("");
    setNoteText("");
    setError("");
  }

  async function addNote(e?: React.FormEvent) {
    e?.preventDefault();
    const text = noteText.trim();
    if (!text) return;
    const res = await fetch("/api/notes", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ text }),
    });
    if (res.ok) {
      const data = await res.json();
      setNotes((prev) => [...prev, data.note]);
      setNoteText("");
    } else if (res.status === 401) {
      setUser(null);
      setNotes([]);
    }
  }

  if (loading) {
    return <p className="text-gray-500">Cargando...</p>;
  }

  if (!user) {
    return (
      <form
        className="flex flex-col gap-3"
        onSubmit={(e) => {
          e.preventDefault();
          auth("login");
        }}
      >
        <input
          className="border rounded px-3 py-2"
          type="email"
          placeholder="Email"
          value={email}
          onChange={(e) => setEmail(e.target.value)}
        />
        <input
          className="border rounded px-3 py-2"
          type="password"
          placeholder="Contraseña"
          value={password}
          onChange={(e) => setPassword(e.target.value)}
        />
        <div className="flex gap-2">
          <button
            type="button"
            className="flex-1 bg-gray-200 hover:bg-gray-300 rounded px-3 py-2"
            onClick={() => auth("register")}
          >
            Crear cuenta
          </button>
          <button
            type="submit"
            className="flex-1 bg-blue-600 hover:bg-blue-700 text-white rounded px-3 py-2"
          >
            Entrar
          </button>
        </div>
        {error && <p className="text-red-600">{error}</p>}
      </form>
    );
  }

  return (
    <div className="flex flex-col gap-4">
      <div className="flex items-center justify-between">
        <p className="font-medium">Hola, {user}</p>
        <button
          className="bg-gray-200 hover:bg-gray-300 rounded px-3 py-1"
          onClick={logout}
        >
          Salir
        </button>
      </div>
      <form className="flex gap-2" onSubmit={addNote}>
        <input
          className="flex-1 border rounded px-3 py-2"
          placeholder="Nota"
          value={noteText}
          onChange={(e) => setNoteText(e.target.value)}
        />
        <button
          type="submit"
          className="bg-blue-600 hover:bg-blue-700 text-white rounded px-3 py-2"
        >
          Agregar
        </button>
      </form>
      {notes.length === 0 ? (
        <p className="text-gray-500">No tenés notas todavía.</p>
      ) : (
        <ul className="flex flex-col gap-2">
          {notes.map((n) => (
            <li key={n.id} className="border rounded px-3 py-2">
              {n.text}
            </li>
          ))}
        </ul>
      )}
    </div>
  );
}

