import { randomBytes, scryptSync, timingSafeEqual } from "crypto";

export type User = {
  email: string;
  salt: string;
  hash: string;
};

export type Note = {
  id: string;
  owner: string;
  text: string;
  createdAt: number;
};

type DB = {
  users: Map<string, User>;
  sessions: Map<string, string>;
  notes: Note[];
};

const g = globalThis as unknown as { __notesDb?: DB };

if (!g.__notesDb) {
  g.__notesDb = {
    users: new Map(),
    sessions: new Map(),
    notes: [],
  };
}

export const db: DB = g.__notesDb;

export const SESSION_COOKIE = "session";

export function normalizeEmail(email: string): string {
  return email.trim().toLowerCase();
}

export function hashPassword(password: string, salt?: string) {
  const s = salt ?? randomBytes(16).toString("hex");
  const hash = scryptSync(password, s, 64).toString("hex");
  return { salt: s, hash };
}

export function verifyPassword(password: string, user: User): boolean {
  const { hash } = hashPassword(password, user.salt);
  const a = Buffer.from(hash, "hex");
  const b = Buffer.from(user.hash, "hex");
  return a.length === b.length && timingSafeEqual(a, b);
}

export function createSession(email: string): string {
  const token = randomBytes(32).toString("hex");
  db.sessions.set(token, email);
  return token;
}

export function getSessionEmail(token: string | undefined): string | null {
  if (!token) return null;
  const email = db.sessions.get(token);
  if (!email || !db.users.has(email)) return null;
  return email;
}

export function destroySession(token: string | undefined) {
  if (token) db.sessions.delete(token);
}

export function newId(): string {
  return randomBytes(8).toString("hex");
}

