"use client";

import { useCallback, useEffect, useState } from "react";

type Note = { id: string; text: string; createdAt: number };

export default function NotesApp() {
  const [loading, setLoading] = useState(true);
  const [user, setUser] = useState<string | null>(null);
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [error, setError] = useState("");
  const [notes, setNotes] = useState<Note[]>([]);
  const [noteText, setNoteText] = useState("");
  const [busy, setBusy] = useState(false);

  const loadNotes = useCallback(async () => {
    const res = await fetch("/api/notes", { cache: "no-store" });
    if (res.ok) {
      const data = await res.json();
      setNotes(data.notes);
    } else {
      setNotes([]);
    }
  }, []);

  useEffect(() => {
    (async () => {
      try {
        const res = await fetch("/api/me", { cache: "no-store" });
        if (res.ok) {
          const data = await res.json();
          setUser(data.email);
          await loadNotes();
        }
      } finally {
        setLoading(false);
      }
    })();
  }, [loadNotes]);

  async function auth(kind: "register" | "login") {
    setError("");
    setBusy(true);
    try {
      const res = await fetch(`/api/${kind}`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ email, password }),
      });
      const data = await res.json().catch(() => ({}));
      if (!res.ok) {
        setError(kind === "login" ? "Datos incorrectos" : data.error || "Error");
        return;
      }
      setUser(data.email);
      setPassword("");
      await loadNotes();
    } finally {
      setBusy(false);
    }
  }

  async function logout() {
    await fetch("/api/logout", { method: "POST" });
    setUser(null);
    setNotes([]);
    setEmail("");
    setPassword("");
    setNoteText("");
    setError("");
  }

  async function addNote() {
    const text = noteText.trim();
    if (!text) return;
    setBusy(true);
    try {
      const res = await fetch("/api/notes", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ text }),
      });
      if (res.ok) {
        const data = await res.json();
        setNotes((prev) => [...prev, data.note]);
        setNoteText("");
      } else if (res.status === 401) {
        setUser(null);
        setNotes([]);
      }
    } finally {
      setBusy(false);
    }
  }

  if (loading) {
    return <p className="text-center text-gray-500">Cargando...</p>;
  }

  if (!user) {
    return (
      <div className="mx-auto w-full max-w-sm space-y-4 rounded-xl bg-white p-6 shadow">
        <h1 className="text-2xl font-bold text-gray-800">Notas privadas</h1>
        <input
          type="email"
          placeholder="Email"
          value={email}
          onChange={(e) => setEmail(e.target.value)}
          className="w-full rounded border border-gray-300 px-3 py-2 text-gray-900"
        />
        <input
          type="password"
          placeholder="Contraseña"
          value={password}
          onChange={(e) => setPassword(e.target.value)}
          onKeyDown={(e) => e.key === "Enter" && auth("login")}
          className="w-full rounded border border-gray-300 px-3 py-2 text-gray-900"
        />
        {error && <p className="text-sm text-red-600">{error}</p>}
        <div className="flex gap-2">
          <button
            onClick={() => auth("register")}
            disabled={busy}
            className="flex-1 rounded bg-gray-200 px-4 py-2 font-medium text-gray-800 hover:bg-gray-300 disabled:opacity-50"
          >
            Crear cuenta
          </button>
          <button
            onClick={() => auth("login")}
            disabled={busy}
            className="flex-1 rounded bg-blue-600 px-4 py-2 font-medium text-white hover:bg-blue-700 disabled:opacity-50"
          >
            Entrar
          </button>
        </div>
      </div>
    );
  }

  return (
    <div className="mx-auto w-full max-w-lg space-y-4 rounded-xl bg-white p-6 shadow">
      <div className="flex items-center justify-between">
        <p className="text-lg font-semibold text-gray-800">Hola, {user}</p>
        <button
          onClick={logout}
          className="rounded bg-gray-200 px-3 py-1 text-sm text-gray-800 hover:bg-gray-300"
        >
          Salir
        </button>
      </div>
      <div className="flex gap-2">
        <input
          placeholder="Nota"
          value={noteText}
          onChange={(e) => setNoteText(e.target.value)}
          onKeyDown={(e) => e.key === "Enter" && addNote()}
          className="flex-1 rounded border border-gray-300 px-3 py-2 text-gray-900"
        />
        <button
          onClick={addNote}
          disabled={busy}
          className="rounded bg-blue-600 px-4 py-2 font-medium text-white hover:bg-blue-700 disabled:opacity-50"
        >
          Agregar
        </button>
      </div>
      {notes.length === 0 ? (
        <p className="text-sm text-gray-500">Todavía no tenés notas.</p>
      ) : (
        <ul className="space-y-2">
          {notes.map((n) => (
            <li
              key={n.id}
              className="rounded border border-gray-200 bg-gray-50 px-3 py-2 text-gray-800"
            >
              {n.text}
            </li>
          ))}
        </ul>
      )}
    </div>
  );
}

