"use client";

import { useState } from "react";
import type { Product } from "@/lib/data";
import SearchBox from "@/components/SearchBox";
import ProductCard from "@/components/ProductCard";

export default function Catalog({ products, onAdd }: { products: Product[]; onAdd: (p: Product) => void }) {
  const [query, setQuery] = useState("");
  const [sortByPrice, setSortByPrice] = useState(false);
  const filtered = products.filter((p) => p.name.toLowerCase().includes(query.toLowerCase()));
  const shown = sortByPrice ? [...filtered].sort((a, b) => a.price - b.price) : filtered;

  return (
    <div className="flex flex-col gap-2">
      <div className="flex items-center gap-2">
        <SearchBox value={query} onChange={setQuery} />
        <button
          type="button"
          onClick={() => setSortByPrice((s) => !s)}
          aria-pressed={sortByPrice}
          className={`rounded border px-3 py-1 text-sm ${
            sortByPrice ? "bg-blue-600 text-white border-blue-600" : "bg-white text-gray-700 border-gray-300"
          }`}
        >
          Ordenar por precio
        </button>
      </div>
      <div className="grid grid-cols-3 gap-2">
        {shown.map((p) => (
          <ProductCard key={p.id} product={p} onAdd={() => onAdd(p)} />
        ))}
      </div>
      {shown.length === 0 && <span className="text-gray-500">Sin resultados</span>}
    </div>
  );
}

