export default function EmployeesRow({
  item,
  onToggle,
}: {
  item: Item;
  onToggle: (id: number) => void;
}) {
  return (
    <div className="flex items-center gap-2">
      <span className="font-semibold">
        {item.name}
        {!item.active && <span className="ml-1 font-normal text-gray-500">(inactivo)</span>}
      </span>
      <span>Sueldo: {item.amount}</span>
      <button
        type="button"
        onClick={() => onToggle(item.id)}
        className="rounded border px-2 py-0.5 text-sm hover:bg-gray-100"
      >
        Alternar
      </button>
    </div>
  );
}

