"use client";

import { useState } from "react";
import { SEED, type Item } from "@/lib/data";
import CouponsForm from "@/components/CouponsForm";
import CouponsList from "@/components/CouponsList";

export default function CouponsPage() {
  const [items, setItems] = useState<Item[]>(SEED.map((i) => ({ ...i })));

  function add(name: string, amount: number) {
    setItems([...items, { id: Date.now(), name, amount, active: true }]);
  }

  function remove(id: number) {
    setItems((prev) => prev.filter((i) => i.id !== id));
  }

  return (
    <div className="flex flex-col gap-2">
      <h2 className="text-xl font-bold">Cupones</h2>
      <CouponsForm onAdd={add} />
      <CouponsList items={items} onDelete={remove} />
    </div>
  );
}

files.components/CouponsRow.tsx:
import type { Item } from "@/lib/data";

export default function CouponsRow({ item, onDelete }: { item: Item; onDelete: (id: number) => void }) {
  return (
    <div className="flex gap-2 items-center">
      <span className="font-semibold">{item.name}</span>
      <span>Descuento: {item.amount}</span>
      <button
        type="button"
        className="px-2 py-0.5 text-sm text-white bg-red-600 rounded hover:bg-red-700"
        onClick={() => onDelete(item.id)}
      >
        Eliminar
      </button>
    </div>
  );
}

